[map] name="Xique-Xique — a igreja matriz" w=56 h=48 sky=moon fog=8,8,14 fog_near=6 fog_far=22 legend=mula
; fase 3: igreja matriz, escola paroquial, pátio e casa paroquial. Lenda: Mula sem cabeça.
; acordam na sala 2 da escola. Freio no altar -> sino no alto da torre (coro -> corrente -> escada) -> janela da torre -> rua.
